test('p0 is the minimum and p100 is the maximum', () => {
  eq(percentile(AMOUNTS, 0), 15);
  eq(percentile(AMOUNTS, 100), 300);
});

test('one value is its own median and every percentile', () => {
  eq(median([7]), 7);
  eq(percentile([7], 33), 7);
  eq(percentile([7], 100), 7);
});

test('nothing to measure is null, not zero', () => {
  eq(median([]), null);
  eq(percentile([], 90), null);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('dedupeFirst keeps the earliest scan of each book', () => {
  eq(scanIds(dedupeFirst(SCANS, isbnOf)), [1, 2, 4]);
  eq(dedupeFirst(SCANS, isbnOf)[0].shelf, 'A1');
});

test('dedupeLast keeps the freshest scan of each book', () => {
  eq(scanIds(dedupeLast(SCANS, isbnOf)), [3, 5, 4]);
  eq(dedupeLast(SCANS, isbnOf)[0].shelf, 'C3');
});

test('both keep the keys in first-seen order', () => {
  const keys = (rows) => rows.map(isbnOf);
  eq(keys(dedupeFirst(SCANS, isbnOf)), ['978-0', '978-1', '978-2']);
  eq(keys(dedupeLast(SCANS, isbnOf)), ['978-0', '978-1', '978-2']);
});

test('a list with no repeats comes back whole, either way', () => {
  const clean = [SCANS[0], SCANS[1], SCANS[3]];
  eq(scanIds(dedupeFirst(clean, isbnOf)), [1, 2, 4]);
  eq(scanIds(dedupeLast(clean, isbnOf)), [1, 2, 4]);
});

test('duplicates lists only the keys that repeat', () => {
  eq(duplicates(SCANS, isbnOf), ['978-0', '978-1']);
  eq(duplicates([SCANS[0], SCANS[1]], isbnOf), []);
});

test('the scans themselves are passed through, not copied', () => {
  ok(dedupeFirst(SCANS, isbnOf)[0] === SCANS[0]);
  ok(dedupeLast(SCANS, isbnOf)[0] === SCANS[2]);
});

test('a composite key keeps rows that differ in either part', () => {
  const key = (s) => `${s.isbn}|${s.shelf}`;
  eq(dedupeFirst(SCANS, key).length, 5);
  eq(duplicates(SCANS, key), []);
});

test('an empty list is empty three ways', () => {
  eq(dedupeFirst([], isbnOf), []);
  eq(dedupeLast([], isbnOf), []);
  eq(duplicates([], isbnOf), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('chunkCount rounds up, and nothing needs no chunks', () => {
  eq(chunkCount(7, 3), 3);
  eq(chunkCount(6, 3), 2);
  eq(chunkCount(1, 3), 1);
  eq(chunkCount(0, 3), 0);
});

test('each chunk reports where it sits in the source', () => {
  const chunks = chunkWithIndex(INVOICES, 3);
  eq(chunks.map((c) => [c.index, c.start, c.end]), [
    [0, 0, 3],
    [1, 3, 6],
    [2, 6, 7],
  ]);
});

test('the last chunk is short, not padded', () => {
  const chunks = chunkWithIndex(INVOICES, 3);
  eq(chunks.at(-1).items.map((i) => i.id), ['in7']);
});

test('every invoice appears exactly once, in order', () => {
  const flat = chunkWithIndex(INVOICES, 3).flatMap((c) => c.items);
  eq(flat.map((i) => i.id), INVOICES.map((i) => i.id));
});

test('globalIndex maps a slot in a chunk back to the source index', () => {
  eq(globalIndex(0, 3, 0), 0);
  eq(globalIndex(1, 3, 2), 5);
  eq(globalIndex(2, 3, 0), 6);
});

test('processInBatches passes the global index, not the local one', () => {
  eq(processInBatches(INVOICES, 3, (invoice, i) => i), [0, 1, 2, 3, 4, 5, 6]);
  eq(processInBatches(INVOICES, 3, (invoice, i) => `${i}:${invoice.id}`).at(-1),
    '6:in7');
});

test('a size at least as big as the list gives one chunk', () => {
  eq(chunkWithIndex(INVOICES, 99).length, 1);
  eq(chunkWithIndex(INVOICES, 99)[0].end, 7);
});

test('an empty list has no chunks, and size 0 is an error', () => {
  eq(chunkWithIndex([], 3), []);
  eq(processInBatches([], 3, (invoice, i) => i), []);
  throws(() => chunkWithIndex(INVOICES, 0), 'size');
});

