export function catalogueLine(products, category) {
  return products
    .filter((p) => p.category === category)
    .map((p) => p.name)
    .join(', ');
}

export function anyExpensiveOutOfStock(products, threshold) {
  return products
    .filter((p) => p.stock === 0)
    .some((p) => p.price > threshold);
