  eq(countBy(PRODUCTS, (p) => p.category), {
    input: 2,
    display: 1,
    adapter: 2,
    desk: 2,
    video: 1,
  });
});

test('counts repeated words', () => {
  eq(countBy(['a', 'b', 'a', 'c', 'a'], (w) => w), { a: 3, b: 1, c: 1 });
