  const rows = [{ name: 'cherry' }, { name: 'Banana' }, { name: 'apple' }];
  eq(sortBy(rows, ['name']).map((r) => r.name), ['apple', 'Banana', 'cherry']);
});

test('items that tie on every spec keep their original order', () => {
  const rows = [
    { g: 'a', n: 1 },
    { g: 'b', n: 2 },
    { g: 'a', n: 3 },
  ];
  eq(sortBy(rows, ['g']).map((r) => r.n), [1, 3, 2]);
});

