  const copy = sortBy(PRODUCTS, []);
  eq(ids(copy), ids(PRODUCTS));
  ok(copy !== PRODUCTS);
});

test('the frozen input is never sorted in place', () => {
  sortBy(PRODUCTS, ['-price']);
  eq(PRODUCTS[0].id, 'p1');
