  eq(merged.plugins, ['timer', 'charts', 'charts', 'export']);
});

test('the union strategy appends and de-duplicates', () => {
  const merged = deepMerge(BASE, PATCH, { arrays: 'union' });
  eq(merged.plugins, ['timer', 'charts', 'export']);
});

